rules.logic:
// Idempotency guard
if (element.dataset.quickActionsInjected === '1') return;

// --- Gather data from the video renderer ---
const renderer = element.closest('ytd-video-renderer');
if (!renderer) return;

// Channel URL
const channelAnchor = renderer.querySelector('ytd-channel-name #text-container a');
const channelHref = channelAnchor ? channelAnchor.href : null;
if (!channelHref) return;

// Video URL (for Add to Playlist)
const videoAnchor = renderer.querySelector('a#video-title');
const videoHref = videoAnchor ? videoAnchor.href : null;
if (!videoHref) return;

// Channel name for tooltip
const channelName = channelAnchor ? channelAnchor.textContent.trim() : 'channel';

// Extract video ID
const videoUrl = new URL(videoHref);
const videoId = videoUrl.searchParams.get('v');

// --- Common button styles ---
const baseStyle = [
  'display: inline-flex',
  'align-items: center',
  'gap: 6px',
  'padding: 6px 12px',
  'border-radius: 18px',
  'border: none',
  'cursor: pointer',
  'font-size: 13px',
  'font-weight: 500',
  'font-family: "Roboto", sans-serif',
  'text-decoration: none',
  'transition: background 0.15s, opacity 0.15s',
  'white-space: nowrap',
  'line-height: 1',
].join(';');

// --- Subscribe button ---
const subscribeBtn = document.createElement('a');
subscribeBtn.href = channelHref + '?sub_confirmation=1';
subscribeBtn.target = '_blank';
subscribeBtn.rel = 'noopener noreferrer';
subscribeBtn.title = 'Subscribe to ' + channelName;
subscribeBtn.setAttribute('style',
  baseStyle + ';' +
  'background: #ff0000;' +
  'color: #fff;'
);
subscribeBtn.addEventListener('mouseover', () => { subscribeBtn.style.opacity = '0.85'; });
subscribeBtn.addEventListener('mouseout',  () => { subscribeBtn.style.opacity = '1'; });

// Bell SVG icon
const bellSvg = `<svg xmlns="http://www.w3.org/2000/svg" height="14" width="14" viewBox="0 0 24 24" fill="currentColor">
  <path d="M12 22c1.1 0 2-.9 2-2h-4c0 1.1.9 2 2 2zm6-6V11c0-3.07-1.63-5.64-4.5-6.32V4c0-.83-.67-1.5-1.5-1.5s-1.5.67-1.5 1.5v.68C7.64 5.36 6 7.92 6 11v5l-2 2v1h16v-1l-2-2z"/>
</svg>`;
subscribeBtn.innerHTML = bellSvg + '<span>Subscribe</span>';

// --- Add to Playlist button ---
const playlistBtn = document.createElement('a');
// Opens the "Save to playlist" dialog via the YouTube playlist add URL
const playlistUrl = videoId
  ? 'https://www.youtube.com/watch?v=' + videoId + '&feature=share'
  : videoHref;
playlistBtn.href = '#';
playlistBtn.title = 'Add to playlist';
playlistBtn.setAttribute('style',
  baseStyle + ';' +
  'background: #f2f2f2;' +
  'color: #0f0f0f;' +
  'border: 1px solid #ccc;'
);
playlistBtn.addEventListener('mouseover', () => { playlistBtn.style.background = '#e5e5e5'; });
playlistBtn.addEventListener('mouseout',  () => { playlistBtn.style.background = '#f2f2f2'; });

// Clicking opens the native YT "Save to playlist" popup by triggering the three-dot menu item
playlistBtn.addEventListener('click', (e) => {
  e.preventDefault();
  e.stopPropagation();
  // Click the action menu button to open the popup menu
  const menuBtn = renderer.querySelector('yt-icon-button#button.dropdown-trigger button');
  if (menuBtn) {
    menuBtn.click();
    // Wait for the popup to render, then click "Save to playlist"
    let attempts = 0;
    const interval = setInterval(() => {
      attempts++;
      const popupItems = document.querySelectorAll(
        'ytd-popup-container tp-yt-paper-listbox ytd-menu-service-item-renderer, ' +
        'ytd-popup-container tp-yt-paper-listbox yt-list-item-view-model'
      );
      for (const item of popupItems) {
        const text = item.textContent.trim().toLowerCase();
        if (text.includes('save') || text.includes('playlist')) {
          item.click();
          clearInterval(interval);
          return;
        }
      }
      if (attempts > 20) clearInterval(interval);
    }, 100);
  }
});

// Playlist (bookmark) SVG icon
const listSvg = `<svg xmlns="http://www.w3.org/2000/svg" height="14" width="14" viewBox="0 0 24 24" fill="currentColor">
  <path d="M14 10H2v2h12v-2zm0-4H2v2h12V6zm4 8v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zM2 16h8v-2H2v2z"/>
</svg>`;
playlistBtn.innerHTML = listSvg + '<span>Add to Playlist</span>';

// --- Wrapper ---
const wrapper = document.createElement('div');
wrapper.setAttribute('style',
  'display: flex; flex-wrap: wrap; gap: 8px; margin-top: 8px; align-items: center;'
);
wrapper.appendChild(subscribeBtn);
wrapper.appendChild(playlistBtn);

element.appendChild(wrapper);
element.dataset.quickActionsInjected = '1';
